<template><main class="save-import"><section class="card import-card"><header><span class="eyebrow">LOCAL MIGRATION</span><h2>迁移旧档</h2><p>仅在本机读取，不上传；不会回放旧聊天，也不会覆盖原导出文件。</p></header><label class="picker"><input type="file" accept=".json,.jsonl,.counterfeit-save.json" @change="pick"/><i class="fa-solid fa-file-arrow-up"></i><span>{{fileName||'选择 .counterfeit-save.json / SillyTavern .jsonl'}}</span></label><p v-if="busy">正在解析与校验……</p><p v-if="error" class="error">{{error}}</p><section v-if="result" class="preview"><div class="status" :class="result.report.status">{{statusText}}</div><dl><template v-for="row in rows" :key="row[0]"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></template></dl><div v-if="result.report.migrationSteps.length"><strong>迁移步骤</strong><ul><li v-for="s in result.report.migrationSteps" :key="s">{{s}}</li></ul></div><div v-if="result.report.addedFields.length"><strong>补全字段</strong><p>{{result.report.addedFields.join('、')}}</p></div><div v-if="result.report.discardedFields.length"><strong>已废弃字段</strong><p>{{result.report.discardedFields.join('、')}}</p></div><div v-if="result.report.warnings.length"><strong>警告</strong><ul><li v-for="s in result.report.warnings" :key="s">{{s}}</li></ul></div><div v-if="result.report.conflicts.length" class="error"><strong>无法迁移</strong><ul><li v-for="s in result.report.conflicts" :key="s">{{s}}</li></ul></div></section><footer><button class="btn-ghost" @click="store.backToTitle()">取消</button><button class="btn-primary" :disabled="!result?.statData||busy" @click="commitResume">迁移并继续</button></footer></section></main></template>
<script setup lang="ts">import{parseChatExport}from'../../存档/parseChatExport';import{migrateParsedSave,parsePortableSave}from'../../存档/portableSave';import{commitPortableResume}from'../../存档/resumeCommit';import type{MigrationResult}from'../../存档/types';import{useOpeningStore}from'./store';const store=useOpeningStore(),busy=ref(false),error=ref(''),fileName=ref(''),result=ref<MigrationResult|null>(null);const statusText=computed(()=>result.value?.report.status==='exact'?'可直接续接':result.value?.report.status==='migratable'?'可迁移':'不兼容');const rows=computed(()=>{const r=result.value?.report;return r?[['来源版本',r.sourceVersion],['存档 Schema',r.schemaVersion??'旧版未标记'],['战役',r.campaignId],['玩家视点',r.playerViewpoint??'未确认'],['场景/日期',`${r.scene??'-'} / ${r.date??'-'}`],['地点',r.location??'未确认'],['恢复楼层',r.recoveredFloor??'官方存档'],['消息数',r.messageCount]]:[]});async function pick(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';result.value=null;fileName.value=file.name;try{const source=file.name.endsWith('.jsonl')?await parseChatExport(file):file.name.endsWith('.counterfeit-save.json')?await parsePortableSave(file):await detectJson(file);result.value=migrateParsedSave(source)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}async function detectJson(file:File){try{return await parsePortableSave(file)}catch{return parseChatExport(file)}}async function commitResume(){if(!result.value?.statData||busy.value)return;busy.value=true;error.value='';try{await commitPortableResume(result.value,{getMessage0:()=>getChatMessages(0),getFloor0Variables:()=>getVariables({type:'message',message_id:0}),getChatVariables:()=>getVariables({type:'chat'}),setMessage0:messages=>setChatMessages(messages as any,{refresh:'affected'}),setFloor0Variables:updater=>updateVariablesWith(updater,{type:'message',message_id:0}),setChatVariables:updater=>updateVariablesWith(updater,{type:'chat'})});window.parent.postMessage({source:'counterfeit-opening',type:'commit-done',commitKind:'resume'},'*');store.step='done'}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}</script>
<style scoped lang="scss">.save-import{min-height:100vh;min-height:100dvh;display:flex;justify-content:center;padding:28px 16px}.import-card{width:100%;max-width:640px;padding:24px;display:grid;gap:18px}header p{color:var(--c-text-muted);line-height:1.6}.eyebrow{font-size:11px;letter-spacing:3px;color:var(--c-primary-strong)}h2{font-size:24px;margin:5px 0}.picker{padding:24px;border:2px dashed var(--c-border-strong);border-radius:12px;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer}.picker input{display:none}.picker i{font-size:28px;color:var(--c-primary)}.preview{display:grid;gap:12px}.status{width:max-content;padding:4px 10px;border-radius:999px}.status.exact{background:#daf4e6;color:#276b49}.status.migratable{background:#fff0c9;color:#775b19}.status.incompatible{background:#ffe0e0;color:#8a3030}dl{display:grid;grid-template-columns:auto 1fr;gap:7px 14px;font-size:13px}dt{color:var(--c-text-muted)}dd{word-break:break-word}.error{color:var(--c-danger);line-height:1.6}ul{padding-left:20px;line-height:1.6}footer{display:flex;justify-content:space-between}</style>
